CREATE TABLE t0(id INTEGER PRIMARY KEY, c0  DEFAULT 'd', c1 TEXT DEFAULT 'd', c2 VARCHAR(10) DEFAULT 'd');
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES(819, '42', 'psi');
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES('beta', 'rho', x'1e14');
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES(-1e308, NULL, x'bb54');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INT CHECK(c0 IS NULL OR length(c0) < 40), c1 VARCHAR(10));
INSERT OR IGNORE INTO t1(c0, c1) VALUES('日本', 'beta');
INSERT OR IGNORE INTO t1(c0, c1) VALUES('NULL', NULL);
INSERT OR IGNORE INTO t1(c0, c1) VALUES(x'538783be', 658);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 NUMERIC DEFAULT 'd', c1 NUMERIC COLLATE NOCASE, c2 INT, c3 REAL, c4 NUMERIC UNIQUE, ref INTEGER REFERENCES t1(id));
SELECT length(''), upper(''), lower(''), substr('', -3, 3), instr('', 'MU'), replace('', 'é', ''), trim(''), ltrim('', 'ab'), hex(''), quote(''), unicode(''), '' LIKE '%', '' GLOB 'a*', char(66, 552), '' || 'MU', '' < 'MU', '' = 'MU' COLLATE NOCASE;
SELECT length('zeta'), upper('zeta'), lower('zeta'), substr('zeta', -3, 0), instr('zeta', 'theta'), replace('zeta', 'é', '_'), trim('zeta'), ltrim('zeta', 'ab'), hex('zeta'), quote('zeta'), unicode('zeta'), 'zeta' LIKE '%é%', 'zeta' GLOB '*[a-m]*', char(83, 344), 'zeta' || 'theta', 'zeta' < 'theta', 'zeta' = 'theta' COLLATE NOCASE;
SELECT length('epsilon'), upper('epsilon'), lower('epsilon'), substr('epsilon', 0, 5), instr('epsilon', '0x1F'), replace('epsilon', '', '_'), trim('epsilon'), ltrim('epsilon', 'ab'), hex('epsilon'), quote('epsilon'), unicode('epsilon'), 'epsilon' LIKE '_', 'epsilon' GLOB 'a*', char(73, 445), 'epsilon' || '0x1F', 'epsilon' < '0x1F', 'epsilon' = '0x1F' COLLATE NOCASE;
SELECT length('x_y'), upper('x_y'), lower('x_y'), substr('x_y', -3, 0), instr('x_y', 'sigma'), replace('x_y', '', ''), trim('x_y'), ltrim('x_y', 'ab'), hex('x_y'), quote('x_y'), unicode('x_y'), 'x_y' LIKE '%é%', 'x_y' GLOB '?', char(74, 285), 'x_y' || 'sigma', 'x_y' < 'sigma', 'x_y' = 'sigma' COLLATE NOCASE;
SELECT length('a%b'), upper('a%b'), lower('a%b'), substr('a%b', 0, 0), instr('a%b', 'theta'), replace('a%b', 'a', 'XY'), trim('a%b'), ltrim('a%b', 'ab'), hex('a%b'), quote('a%b'), unicode('a%b'), 'a%b' LIKE '_', 'a%b' GLOB '*[a-m]*', char(66, 596), 'a%b' || 'theta', 'a%b' < 'theta', 'a%b' = 'theta' COLLATE NOCASE;
SELECT length('phi'), upper('phi'), lower('phi'), substr('phi', 3, 0), instr('phi', '0x1F'), replace('phi', 'a', ''), trim('phi'), ltrim('phi', 'ab'), hex('phi'), quote('phi'), unicode('phi'), 'phi' LIKE '%', 'phi' GLOB '*[a-m]*', char(89, 949), 'phi' || '0x1F', 'phi' < '0x1F', 'phi' = '0x1F' COLLATE NOCASE;
SELECT length('it''s'), upper('it''s'), lower('it''s'), substr('it''s', -2, 5), instr('it''s', 'delta'), replace('it''s', 'é', ''), trim('it''s'), ltrim('it''s', 'ab'), hex('it''s'), quote('it''s'), unicode('it''s'), 'it''s' LIKE '%a_', 'it''s' GLOB '*[a-m]*', char(81, 960), 'it''s' || 'delta', 'it''s' < 'delta', 'it''s' = 'delta' COLLATE NOCASE;
SELECT count(*), count(ref), sum(ref), total(ref), avg(ref), min(ref), max(ref), count(DISTINCT ref) FROM t2;
SELECT ref, count(*), group_concat(id, ';') FROM (SELECT * FROM t2 ORDER BY id) GROUP BY ref ORDER BY ref;
SELECT length('-7'), upper('-7'), lower('-7'), substr('-7', 4, 3), instr('-7', 'sigma'), replace('-7', 'a', ''), trim('-7'), ltrim('-7', 'ab'), hex('-7'), quote('-7'), unicode('-7'), '-7' LIKE '_', '-7' GLOB '*', char(74, 969), '-7' || 'sigma', '-7' < 'sigma', '-7' = 'sigma' COLLATE NOCASE;
SELECT x'zz';
